"""CANONICAL: Build standardized daily AI art report.

Usage:
  python3 /home/ubuntu/.hermes/scripts/build_report_canonical.py

Output: /home/ubuntu/.hermes/cron/report.html

Section order (FIXED - do not change):
  1. Pixiv SFW (5)
  2. Pixiv R18 (5)
  3. SeaArt (5)
  4. CivitAI (5)
  5. Danbooru (5)
  6. PixAI (5)
  7. Blue Archive Fanart (5 Pixiv + 5 PixAI)
  8. Reddit Nổi Bật
  9. Models Mới (HuggingFace)

Data sources (run these BEFORE this script):
  - /tmp/hermes_report/seaart.json
  - /tmp/hermes_report/pixiv_sfw.json
  - /tmp/hermes_report/pixiv_r18.json
  - /tmp/hermes_report/danbooru.json
  - /tmp/hermes_report/pixai.json
  - /tmp/hermes_report/civitai.json
  - /tmp/hermes_report/ba_pixiv.json
  - /tmp/hermes_report/ba_pixai.json
  - /tmp/hermes_report/hf_models.json
  - /tmp/hermes_report/reddit.json
"""
import hashlib
import json, os, subprocess, sys
from html import escape
from datetime import datetime

CACHE_DIR = os.environ.get("HERMES_IMAGE_DIR", "/home/ubuntu/.hermes/cron/images")
REPORT_DIR = os.environ.get("HERMES_REPORT_DIR", "/home/ubuntu/.hermes/cron")
DATA_DIR = os.environ.get("HERMES_DATA_DIR", "/tmp/hermes_report")
BASE_URL = os.environ.get("HERMES_BASE_URL", "http://150.230.56.153:8002")

os.makedirs(CACHE_DIR, exist_ok=True)
os.makedirs(DATA_DIR, exist_ok=True)

today = datetime.utcnow().strftime('%d/%m/%Y')

def download(url, outpath, referer=None, ua=None):
    tmp_path = outpath + '.tmp'
    if os.path.exists(tmp_path):
        os.remove(tmp_path)
    cmd = ['curl', '-sL', '-o', tmp_path]
    if referer:
        cmd.extend(['-H', f'Referer: {referer}'])
    if ua:
        cmd.extend(['-H', f'User-Agent: {ua}'])
    cmd.extend(['-w', '%{http_code}', url])
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=20)
        if r.stdout.strip() == '200' and os.path.exists(tmp_path) and os.path.getsize(tmp_path) > 100:
            os.replace(tmp_path, outpath)
            return True
        return False
    except (subprocess.TimeoutExpired, FileNotFoundError) as e:
        print(f'⚠️ Download failed for {url}: {e}', file=sys.stderr)
        return False
    finally:
        if os.path.exists(tmp_path):
            os.remove(tmp_path)

def img_url(fname):
    path = os.path.join(CACHE_DIR, fname)
    cache_buster = int(os.path.getmtime(path)) if os.path.exists(path) else 0
    return f'{BASE_URL}/images/{fname}?v={cache_buster}'

def download_pixiv(url, outpath):
    tmp_path = outpath + '.tmp'
    if os.path.exists(tmp_path):
        os.remove(tmp_path)
    try:
        r = subprocess.run(
            ['python3', os.path.join(REPORT_DIR, 'pixiv_downloader.py'), url, tmp_path],
            capture_output=True, text=True, timeout=30
        )
        if r.returncode == 0 and os.path.exists(tmp_path) and os.path.getsize(tmp_path) > 500:
            os.replace(tmp_path, outpath)
            return True
        return False
    except (subprocess.TimeoutExpired, FileNotFoundError) as e:
        print(f'⚠️ Pixiv download failed for {url}: {e}', file=sys.stderr)
        return False
    finally:
        if os.path.exists(tmp_path):
            os.remove(tmp_path)

def fmt_title(t):
    """Return empty string for meaningless titles, else strip HTML entities."""
    if not t:
        return ''
    if not isinstance(t, str):
        return ''
    t = t.replace('</h3>', '').replace('<h3>', '').strip()
    if t.lower() in ('(no title)', 'untitled', '', 'none'):
        return ''
    return t

def load_json(name, default=None):
    if default is None:
        default = []
    path = os.path.join(DATA_DIR, name)
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except Exception as e:
        print(f'⚠️ Skip {name}: {e}')
        return default

def write_atomic(path, content):
    tmp_path = path + '.tmp'
    try:
        with open(tmp_path, 'w', encoding='utf-8') as f:
            f.write(content)
        os.replace(tmp_path, path)
    finally:
        if os.path.exists(tmp_path):
            os.remove(tmp_path)

def resize_cached(fname, path):
    resized = resize(path)
    if not resized:
        return fname

    root, ext = os.path.splitext(fname)
    if ext.lower() == '.webp':
        new_fname = root + '.jpg'
        new_path = os.path.join(CACHE_DIR, new_fname)
        os.replace(path, new_path)
        return new_fname

    return fname

def resize(path):
    """Resize image if over 2MB (anh yêu cầu threshold 2MB, q:v 3)."""
    sz = os.path.getsize(path)
    if sz <= 2 * 1024 * 1024:
        return False

    tmp = os.path.join('/tmp', f'resize_{os.urandom(4).hex()}.jpg')
    cmd = [
        'ffmpeg', '-y', '-i', path,
        '-frames:v', '1',
        '-q:v', '3', '-pix_fmt', 'yuvj444p',
        '-vf', "scale='min(1200,iw)':'min(1800,ih)':force_original_aspect_ratio=decrease",
        '-sws_flags', 'lanczos', tmp
    ]

    try:
        r = subprocess.run(cmd, capture_output=True, timeout=30)
        if r.returncode != 0:
            if r.stderr:
                print(r.stderr.decode('utf-8', errors='replace'), file=sys.stderr, end='')
            return False

        if not os.path.exists(tmp) or os.path.getsize(tmp) <= 500:
            return False

        if os.path.getsize(tmp) < os.path.getsize(path):
            os.replace(tmp, path)
            return True
    except subprocess.TimeoutExpired as e:
        print(f'ffmpeg resize timed out for {path}: {e}', file=sys.stderr)
        return False
    except FileNotFoundError as e:
        print(f'ffmpeg resize failed for {path}: {e}', file=sys.stderr)
        return False
    finally:
        if os.path.exists(tmp):
            os.remove(tmp)

    return False

