DG_JS = '''<script>
document.addEventListener("DOMContentLoaded",function(){
  document.querySelectorAll(".thumb-shell").forEach(function(s){var i=s.querySelector("img");if(!i||!i.getAttribute("src")){s.classList.add("no-src","is-error");return}if(i.complete&&i.naturalWidth>0)s.classList.add("is-loaded");i.addEventListener("load",function(){s.classList.add("is-loaded")});i.addEventListener("error",function(){s.classList.add("is-error");i.removeAttribute("src");i.style.display="none"})});
  if(typeof lucide !== "undefined") lucide.createIcons({attrs:{"stroke-width":1.75}});
});
</script>'''

def _dg_card(item, is_trend=False):
    if not item:
        return '<div class="empty-card"><i data-lucide="image"></i><span>No data</span></div>'
    cls = 'trend-card' if is_trend else 'art-card'
    score_val = item.get('score', 0)
    metrics = f'<span class="metric"><i data-lucide="heart" fill="currentColor"></i>{score_val}</span>' if score_val else ''
    title = item.get('title') or ''
    author = item.get('author') or ''
    alt = escape(title or 'Artwork')
    img_html = f'<img src="{escape(item.get("img",""))}" alt="{alt}" loading="lazy" decoding="async">' if item.get('img') else '<img alt="Artwork" loading="lazy" decoding="async">'
    title_html = f'<h3 class="card-title">{escape(title)}</h3>' if title else '<h3 class="card-title is-untitled">Untitled</h3>'
    author_html = f'<span class="card-author">{escape(author)}</span>' if author else ''
    metric_row_html = f'<div class="metric-row">{metrics}</div>' if metrics else ''
    return (
        f'<article class="{cls}">'
        f'<div class="badge-row"><span class="source-badge">{escape(item.get("label","Source"))}</span></div>'
        f'<div class="thumb-shell">{img_html}<div class="thumb-fallback"><i data-lucide="image-off"></i><span>Preview</span></div></div>'
        f'<div class="card-overlay">'
        f'{title_html}'
        f'<div class="card-meta">'
        f'{author_html}'
        f'{metric_row_html}'
        f'</div>'
        f'<a class="source-link" href="{escape(item.get("url","#"))}" target="_blank" rel="noopener"><i data-lucide="external-link"></i></a>'
        f'</div></article>'
    )

def _dg_section(logo_key, items, r18=False):
    cards = ''.join(_dg_card(it) for it in items) if items else '<div class="empty-card"><i data-lucide="folder-open"></i><span>No data</span></div>'
    r18_html = f'<span class="r18-badge">R18+</span>' if r18 else ''
    info = LOGO_CLASSES.get(logo_key, {})
    extra_cls = info.get('class', '')
    logo_cls = f'section-logo {extra_cls}' if extra_cls else 'section-logo'
    logo_html = f'<span class="{logo_cls}">{LOGO.get(logo_key,"")}</span>' if LOGO.get(logo_key) else ''
    heading_html = ''  # SVG logo is sufficient, no text heading needed
    return f'<section class="section"><div class="section-header">{logo_html}{heading_html}{r18_html}</div><div class="image-grid">{cards}</div></section>'

def _compact_count(n):
    """Format number: 999 -> 999, 1200 -> 1.2k, 16200 -> 16.2k, 1240000 -> 1.2M"""
    if n >= 1_000_000:
        return f'{n/1_000_000:.1f}M'.replace('.0', '')
    if n >= 10_000:
        return f'{n/1_000:.0f}k'
    if n >= 1_000:
        return f'{n/1_000:.1f}k'.replace('.0', '')
    return str(n)

def _relative_time(iso_str):
    """Convert ISO datetime string to 'X days ago' format."""
    if not iso_str:
        return None
    try:
        from datetime import datetime, timezone
        dt = datetime.fromisoformat(iso_str.replace('Z', '+00:00'))
        now = datetime.now(timezone.utc)
        delta = now - dt
        days = delta.days
        if days < 0:
            return None
        if days == 0:
            return 'Today'
        if days == 1:
            return 'Yesterday'
        return f'{days} days ago'
    except Exception:
        return None

def _build_status_html():
    status_path = os.path.join(DATA_DIR, 'source_status.json')
    try:
        with open(status_path, encoding='utf-8') as f:
            st = json.load(f)
    except Exception:
        return ''

    def fmt_time(value):
        if not value:
            return 'unknown'
        return str(value).replace('T', ' ').replace('+00:00', ' UTC')

    sources = st.get('sources', {})
    if not isinstance(sources, dict):
        return ''

    total = len(sources)
    fresh_count = 0
    stale_count = 0
    failed_count = 0
    total_items = 0
    chips = []

    for name, source in sources.items():
        if not isinstance(source, dict):
            continue
        ok = bool(source.get('ok'))
        stale = bool(source.get('stale'))
        safe_name = escape(str(name))
        count = source.get('items', 0)
        try:
            count = int(count)
        except Exception:
            count = 0
        total_items += count

        if ok and not stale:
            fresh_count += 1
            try:
                duration = float(source.get("duration_sec", 0))
            except Exception:
                duration = 0.0
            label = f'{safe_name} {count}'
            title = f'OK · {count} items · {duration:.1f}s · updated {fmt_time(source.get("updated_at"))}'
            aria = f'OK · {duration:.1f}s · updated {fmt_time(source.get("updated_at"))}'
            chip_cls = 'fresh'
        elif (not ok) and stale:
            stale_count += 1
            label = f'{safe_name} stale · {count}'
            error = str(source.get("error", "unknown"))
            title = f'STALE fallback · {count} old items · last success {fmt_time(source.get("last_success_at"))} · error: {error}'
            aria = f'last success {fmt_time(source.get("last_success_at"))} · error: {error}'
            chip_cls = 'stale'
        else:
            failed_count += 1
            label = f'{safe_name} failed'
            error = str(source.get("error", "unknown"))
            title = f'FAILED · no usable JSON · error: {error}'
            aria = f'no usable JSON · error: {error}'
            chip_cls = 'failed'

        chips.append(
            f'<span class="source-chip {chip_cls}" title="{escape(title)}" aria-label="{escape(aria)}">'
            f'<span class="dot" aria-hidden="true">●</span>'
            f'<span>{label}</span></span>'
        )

    # Build summary line
    summary_parts = []
    if stale_count == 0 and failed_count == 0:
        summary_text = f'{total}/{total} sources fresh · {total_items} items'
        summary_dot = 'fresh'
    else:
        summary_parts.append(f'{fresh_count}/{total} sources fresh')
        if stale_count:
            summary_parts.append(f'{stale_count} stale')
        if failed_count:
            summary_parts.append(f'{failed_count} failed')
        summary_parts.append(f'{total_items} items')
        summary_text = ' · '.join(summary_parts)
        if stale_count and not failed_count:
            summary_dot = 'amber'
        elif failed_count:
            summary_dot = 'red'
        else:
            summary_dot = 'fresh'

    chips_html = '<div class="source-grid">' + ''.join(chips) + '</div>' if chips else ''

    return (
        '<div class="footer-summary">'
        f'<span class="summary-dot {summary_dot}"></span>'
        f'<span>{escape(summary_text)}</span>'
        '</div>'
        '<details class="source-details">'
        '<summary>Source details</summary>'
        f'{chips_html}'
        '</details>'
    )

def build_demo_gallery():
    pixiv_sfw = load_json('pixiv_sfw.json')
    pixiv_r18 = load_json('pixiv_r18.json')
    seaart = load_json('seaart.json')
    civitai_raw = load_json('civitai.json')
    civitai = civitai_raw if isinstance(civitai_raw, list) else civitai_raw.get('items', []) if isinstance(civitai_raw, dict) else []
    danbooru = load_json('danbooru.json')
    pixai = load_json('pixai.json')
    ba_pixiv = load_json('ba_pixiv.json')
    ba_pixai = load_json('ba_pixai.json')
    reddit = load_json('reddit.json')
    hf = load_json('hf_models.json')

    # TREND HOT - 8 best
    trend_specs = [
        ('pixiv', pixiv_sfw, 'pixiv_sfw', 'jpg'),
        ('pixiv_r18', pixiv_r18, 'pixiv_r18', 'jpg'),
        ('seaart', seaart, 'seaart', 'webp'),
        ('civitai', civitai, 'civitai', 'jpg'),
        ('danbooru', danbooru, 'danbooru', 'jpg'),
        ('pixai', pixai, 'pixai', 'webp'),
        ('ba_pixiv', ba_pixiv, 'ba_pixiv', 'jpg'),
        ('ba_pixai', ba_pixai, 'ba_pixai', 'webp'),
    ]
    trend_cards_html = ''
    for i, (src, data, prefix, ext) in enumerate(trend_specs):
        item, img = _d_best(src, data, prefix, ext)
        if item:
            t = fmt_title(item.get('title'))
            if not t:
                t = fmt_title(item.get('model_name')) or fmt_title(item.get('name'))
            if not t:
                t = ''
            author = item.get('user_name') or item.get('author') or item.get('username') or item.get('artist') or ''
            score = _d_score(src, item)
            url = item.get('url', '#')
            if src == 'civitai' and item.get('id'):
                url = f'https://civitai.red/images/{item.get("id")}'
            rec = {'title': t, 'author': author, 'score': score, 'img': img, 'url': url, 'label': _d_label(src)}
            trend_cards_html += _dg_card(rec, is_trend=True)
        else:
            trend_cards_html += '<div class="empty-card"><i data-lucide="image"></i><span>No data</span></div>'

    # SOURCE SECTIONS
    src_sections = [
        ('pixiv', _d_items('pixiv', pixiv_sfw, 'pixiv_sfw', 'jpg'), False),
        ('pixiv', _d_items('pixiv_r18', pixiv_r18, 'pixiv_r18', 'jpg'), True),
        ('seaart', _d_items('seaart', seaart, 'seaart', 'webp'), False),
        ('civitai', _d_items('civitai', civitai, 'civitai', 'jpg'), False),
        ('danbooru', _d_items('danbooru', danbooru, 'danbooru', 'jpg'), False),
        ('pixai', _d_items('pixai', pixai, 'pixai', 'webp'), False),
    ]
    source_html = ''.join(_dg_section(lk, items, r18) for lk, items, r18 in src_sections)

    # BLUE ARCHIVE
    ba_items = _d_items('ba_pixiv', ba_pixiv, 'ba_pixiv', 'jpg') + _d_items('ba_pixai', ba_pixai, 'ba_pixai', 'webp')
    ba_cards = ''.join(_dg_card(it) for it in ba_items[:10]) if ba_items else '<div class="empty-card"><i data-lucide="folder-open"></i><span>No data</span></div>'
    ba_html = f'<section class="section ba-section"><div class="section-header"><span class="section-logo logo-bluearchive">{LOGO.get("bluearchive","")}</span></div><div class="ba-grid" tabindex="0" role="region" aria-label="Blue Archive artworks">{ba_cards}</div></section>'

    # REDDIT
    reddit_html = ''
    if isinstance(reddit, list) and reddit:
        sd = [p for p in reddit if p.get('subreddit') == 'StableDiffusion'][:5]
        llm = [p for p in reddit if p.get('subreddit') == 'LocalLLaMA'][:5]
        reddit_html = '<div class="link-panel"><div class="section-header"><span class="section-logo logo-reddit">{}</span></div><div class="link-list">'.format(LOGO.get('reddit',''))
        for posts, label in [(sd, 'r/StableDiffusion'), (llm, 'r/LocalLLaMA')]:
                for p in posts:
                    t = str(p.get('title') or '').replace('</h3>','').replace('<h3>','').strip()
                    subreddit = str(p.get('subreddit') or 'reddit')
                    author = str(p.get('author') or '?')
                    url = str(p.get('url') or '#')
                    href = url if url.startswith(('http://', 'https://')) else f'https://reddit.com/{url.lstrip("/")}'
                    reddit_html += (
                        f'<a class="reddit-row" href="{escape(href)}" target="_blank" rel="noopener">'
                        f'<span class="reddit-vote"><i data-lucide="chevron-up"></i><span></span></span>'
                        f'<span class="reddit-body"><span class="reddit-title">{escape(t)}</span>'
                        f'<span class="reddit-meta"><span class="subreddit-pill">{escape(subreddit)}</span>'
                        f'<span>by {escape(author)}</span></span></span>'
                        f'<i data-lucide="external-link" class="reddit-open"></i></a>'
                    )
        reddit_html += '</div></div>'

    # HUGGINGFACE
    hf_html = ''
    if isinstance(hf, list) and hf:
        hf_html = '<div class="link-panel"><div class="section-header"><span class="section-logo logo-huggingface">{}</span></div><div class="link-list">'.format(LOGO.get('huggingface',''))
        for m in hf[:8]:
            if not isinstance(m, dict):
                continue
            mid = str(m.get('modelId') or m.get('id') or '?')
            downloads = m.get('downloads', 0)
            likes = m.get('likes', 0)
            rel_time = _relative_time(m.get('lastModified'))
            sep = '<span style="color:var(--border)">\u2022</span>'
            time_html = f'<span>{escape(rel_time)}</span>{sep}' if rel_time else ''
            hf_html += (
                f'<a class="hf-row" href="https://huggingface.co/{escape(mid)}" target="_blank" rel="noopener">'
                f'<span class="hf-avatar">HF</span><span class="hf-body">'
                f'<span class="hf-title">{escape(mid)}</span>'
                f'<span class="hf-meta">{time_html}<i data-lucide="download"></i>{_compact_count(downloads)}'
                f'{sep}<i data-lucide="heart"></i>{_compact_count(likes)}</span></span></a>'
            )
        hf_html += '</div></div>'

    html = f'''<!DOCTYPE html>
<html lang="vi">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Pastel Dreamscape — {today}</title>
<script src="https://unpkg.com/lucide@latest"></script>
<style>{DG_CSS}\n{_gen_logo_css()}</style>
</head>
<body>
<svg aria-hidden="true" style="position:absolute;width:0;height:0;overflow:hidden">
  <defs>
    <linearGradient id="flame-grad" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#ff6b35"/>
      <stop offset="50%" stop-color="#ff4500"/>
      <stop offset="100%" stop-color="#e8291a"/>
    </linearGradient>
  </defs>
</svg>
<main class="report-shell">
  <header class="hero hero-ribbon">
    <div class="hero-ribbon-inner">
      <h1>Bản tin ảnh Anime AI</h1>
    </div>
    <div class="hero-date">{today}</div>
  </header>

<div class="image-grid-wrap">
<section class="section">
    <div class="section-header trend-meter">
      <span class="trend-line"></span>
      <i data-lucide="flame"></i>
      <span class="trend-label">TREND HOT</span>
      <span class="trend-line"></span>
    </div>
    <div class="trend-mosaic" tabindex="0" role="region" aria-label="Trending artworks">{trend_cards_html}</div>
  </section>

  {source_html}

  {ba_html}
  </div>

  <section class="section">
    <div class="links-grid">
      {reddit_html}
      {hf_html}
    </div>
  </section>

  <footer class="report-footer">
    {_build_status_html()}
    <div class="footer-divider"></div>
    <div class="footer-main">
      <div class="footer-generated">Generated {today} · Hermes Report System</div>
    </div>
  </footer>
</main>
{DG_JS}
</body>
</html>'''

    ts = datetime.now().strftime('%Y-%m-%d-%H-%M-%S')
    dated_name = f'report-{ts}.html'
    dated_path = os.path.join(REPORT_DIR, dated_name)
    write_atomic(REPORT_OUT, html)
    write_atomic(dated_path, html)
    print(f'✅ Report: {REPORT_OUT} ({len(html)} bytes)')
    print(f'📁 History: {dated_path}')

if __name__ == '__main__':
    build_demo_gallery()
